import{_ as d,c as r,o as e,aj as a}from"./chunks/framework.B5VMNd4r.js";const c=JSON.parse('{"title":"第1章 AI图片创作工具——从生成到编辑的开源方案","description":"","frontmatter":{},"headers":[],"relativePath":"handbook/ai-tools/chapter_1.md","filePath":"handbook/ai-tools/chapter_1.md","lastUpdated":1783615807000}'),o={name:"handbook/ai-tools/chapter_1.md"};function i(l,t,h,n,s,p){return e(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="第1章-ai图片创作工具——从生成到编辑的开源方案" tabindex="-1">第1章 AI图片创作工具——从生成到编辑的开源方案 <a class="header-anchor" href="#第1章-ai图片创作工具——从生成到编辑的开源方案" aria-label="Permalink to “第1章 AI图片创作工具——从生成到编辑的开源方案”">​</a></h1><p>试了20多款AI图片工具后，我留下了这5个开源的。</p><p>我是怕浪猫，一个在AI工具坑里摸爬滚打了两年的创作者。这个系列帮你从海量AI工具中筛出真正好用的开源方案，每章都有对比表格和实操指南，收藏即用。</p><h2 id="_1-1-ai图片生成核心模型-sdxl与flux-1" tabindex="-1">1.1 AI图片生成核心模型：SDXL与FLUX.1 <a class="header-anchor" href="#_1-1-ai图片生成核心模型-sdxl与flux-1" aria-label="Permalink to “1.1 AI图片生成核心模型：SDXL与FLUX.1”">​</a></h2><p>2025年开源图片生成领域，两个名字绕不开：SDXL和FLUX.1。</p><p><strong>SDXL（Stable Diffusion XL）</strong></p><p>Stability AI出品，目前开源生态最成熟的模型。Civitai社区上有数万个微调模型和LoRA，风格覆盖从写实到二次元、从油画到3D渲染。</p><table tabindex="0"><thead><tr><th>参数</th><th>说明</th></tr></thead><tbody><tr><td>分辨率</td><td>1024x1024（原生）</td></tr><tr><td>显存需求</td><td>8GB起（FP16）</td></tr><tr><td>许可证</td><td>CreativeML Open RAIL++-M</td></tr><tr><td>社区生态</td><td>Civitai数万模型/LoRA</td></tr><tr><td>适用场景</td><td>风格多样化、LoRA微调</td></tr></tbody></table><p><strong>FLUX.1</strong></p><p>Black Forest Labs（前Stability AI核心团队）出品，2025年11月已更新到FLUX.2。目前开源图片生成的画质天花板。</p><table tabindex="0"><thead><tr><th>版本</th><th>特点</th><th>许可证</th></tr></thead><tbody><tr><td>FLUX.1 schnell</td><td>1-4步快速生成</td><td>Apache 2.0</td></tr><tr><td>FLUX.1 dev</td><td>最高画质，非商用</td><td>Non-commercial</td></tr><tr><td>FLUX.2</td><td>多图参考、字符一致性</td><td>部分开源</td></tr></tbody></table><blockquote><p>选模型不是选&quot;最强&quot;，而是选&quot;最适合&quot;。SDXL赢在生态，FLUX赢在画质。</p></blockquote><p><strong>怎么选？</strong></p><table tabindex="0"><thead><tr><th>你的需求</th><th>推荐模型</th></tr></thead><tbody><tr><td>新手入门</td><td>SDXL（教程多、模型多）</td></tr><tr><td>追求最高画质</td><td>FLUX.1 dev</td></tr><tr><td>商用项目</td><td>FLUX.1 schnell（Apache 2.0）</td></tr><tr><td>需要训练自己的LoRA</td><td>SDXL（LoRA训练生态成熟）</td></tr><tr><td>中文文字渲染</td><td>FLUX.1（文字渲染能力强）</td></tr></tbody></table><h2 id="_1-2-comfyui-节点化工作流的王者" tabindex="-1">1.2 ComfyUI：节点化工作流的王者 <a class="header-anchor" href="#_1-2-comfyui-节点化工作流的王者" aria-label="Permalink to “1.2 ComfyUI：节点化工作流的王者”">​</a></h2><p>如果说AI图片生成有一个&quot;专业版&quot;工具，那就是ComfyUI。</p><p><strong>核心特点</strong></p><ul><li>节点化设计：把生成流程拆成可视化节点，拖拽连接即可</li><li>模型支持全面：SD1.x/SD2.x/SDXL/SD3/FLUX/PixArt等主流模型全覆盖</li><li>工作流可导出：一个JSON文件就能分享完整工作流</li><li>插件生态丰富：ControlNet、LoRA、Inpainting、超分辨率等</li><li>显存优化好：同样显存下比WebUI能跑更大的模型</li></ul><p><strong>3步快速上手</strong></p><table tabindex="0"><thead><tr><th>步骤</th><th>操作</th><th>说明</th></tr></thead><tbody><tr><td>1. 安装</td><td>下载ComfyUI便携版</td><td>解压即用，无需配置环境</td></tr><tr><td>2. 放模型</td><td>将.safetensors文件放入models/checkpoints/</td><td>SDXL或FLUX模型</td></tr><tr><td>3. 生成</td><td>浏览器访问127.0.0.1:8188</td><td>加载默认工作流，输入提示词</td></tr></tbody></table><p><strong>ComfyUI vs WebUI对比</strong></p><table tabindex="0"><thead><tr><th>维度</th><th>ComfyUI</th><th>WebUI(A1111)</th></tr></thead><tbody><tr><td>操作方式</td><td>节点拖拽</td><td>标签页表单</td></tr><tr><td>上手难度</td><td>中等</td><td>简单</td></tr><tr><td>灵活度</td><td>极高</td><td>中等</td></tr><tr><td>显存效率</td><td>优秀</td><td>良好</td></tr><tr><td>工作流复用</td><td>JSON导出</td><td>参数保存</td></tr><tr><td>适合人群</td><td>进阶用户</td><td>新手用户</td></tr></tbody></table><blockquote><p>ComfyUI的学习曲线在前3天最陡，但一旦过了那个坎，你会再也回不去标签页。</p></blockquote><h2 id="_1-3-webui-a1111-新手友好的标签页操作" tabindex="-1">1.3 WebUI(A1111)：新手友好的标签页操作 <a class="header-anchor" href="#_1-3-webui-a1111-新手友好的标签页操作" aria-label="Permalink to “1.3 WebUI(A1111)：新手友好的标签页操作”">​</a></h2><p>WebUI全称Stable Diffusion WebUI，也叫A1111（作者名）。它是很多人接触AI图片生成的第一个工具。</p><p><strong>为什么新手推荐WebUI</strong></p><ul><li>界面直观：文生图、图生图、局部重绘都是独立标签页</li><li>参数可视化：采样器、步数、CFG都用滑块控制</li><li>一键安装：Windows便携版解压即用</li><li>社区教程多：B站、YouTube上 hundreds个教程</li></ul><p><strong>核心功能一览</strong></p><table tabindex="0"><thead><tr><th>功能</th><th>说明</th></tr></thead><tbody><tr><td>txt2img</td><td>文生图，基础生成</td></tr><tr><td>img2img</td><td>图生图，基于参考图生成</td></tr><tr><td>Inpaint</td><td>局部重绘，遮罩区域重新生成</td></tr><tr><td>Extras</td><td>图片放大、超分辨率</td></tr><tr><td>Checkpoint Merger</td><td>模型合并</td></tr><tr><td>Train</td><td>LoRA训练（基础）</td></tr><tr><td>Extensions</td><td>插件管理</td></tr></tbody></table><p><strong>WebUI常用参数速查</strong></p><table tabindex="0"><thead><tr><th>参数</th><th>推荐值</th><th>说明</th></tr></thead><tbody><tr><td>采样器</td><td>DPM++ 2M Karras</td><td>速度与质量平衡好</td></tr><tr><td>步数</td><td>20-30</td><td>超过30收益递减</td></tr><tr><td>CFG Scale</td><td>7-9</td><td>太高会过曝</td></tr><tr><td>Denoising</td><td>0.5-0.7</td><td>图生图用，越高变化越大</td></tr><tr><td>Seed</td><td>-1</td><td>随机，固定可复现</td></tr></tbody></table><h2 id="_1-4-图像编辑开源方案-gimp与ai插件生态" tabindex="-1">1.4 图像编辑开源方案：GIMP与AI插件生态 <a class="header-anchor" href="#_1-4-图像编辑开源方案-gimp与ai插件生态" aria-label="Permalink to “1.4 图像编辑开源方案：GIMP与AI插件生态”">​</a></h2><p>AI生成只是第一步，后期编辑同样重要。开源图像编辑领域，GIMP是当之无愧的王者。</p><p><strong>GIMP 3.x新特性</strong></p><p>2025年GIMP迎来30周年纪念，3.x版本带来了重要更新：</p><table tabindex="0"><thead><tr><th>特性</th><th>说明</th></tr></thead><tbody><tr><td>链接图层</td><td>导入外部SVG文件，自动同步更新</td></tr><tr><td>矢量图层</td><td>可编辑路径，保持线条清晰</td></tr><tr><td>PSD兼容性</td><td>更好的Photoshop文件导入</td></tr><tr><td>跨平台</td><td>Windows/macOS/Linux全支持</td></tr><tr><td>插件系统</td><td>支持Python脚本扩展</td></tr></tbody></table><p><strong>GIMP + AI的工作流</strong></p><p>GIMP本身不内置AI生成，但可以通过插件连接AI模型：</p><table tabindex="0"><thead><tr><th>插件</th><th>功能</th></tr></thead><tbody><tr><td>GIMP-StableDiffusion</td><td>在GIMP中调用SD模型</td></tr><tr><td>resynthesizer</td><td>智能内容填充（类似PS内容识别）</td></tr><tr><td>G&#39;MIC</td><td>AI降噪、风格化滤镜</td></tr><tr><td>wavelet decompose</td><td>频率分离修图</td></tr></tbody></table><p><strong>其他开源图像编辑工具</strong></p><table tabindex="0"><thead><tr><th>工具</th><th>定位</th><th>特点</th></tr></thead><tbody><tr><td>Photopea</td><td>在线版PS替代</td><td>浏览器运行，界面接近PS</td></tr><tr><td>Krita</td><td>数字绘画</td><td>支持AI上色、动画</td></tr><tr><td>Inkscape</td><td>矢量编辑</td><td>类似Illustrator</td></tr><tr><td>Darktable</td><td>RAW照片处理</td><td>类似Lightroom</td></tr></tbody></table><blockquote><p>开源图像编辑工具的组合拳：GIMP做编辑 + Krita做绘画 + Photopea做快速在线编辑。三件套替代PS，零成本。</p></blockquote><h2 id="_1-5-实战对比-不同工具的出图效率与质量" tabindex="-1">1.5 实战对比：不同工具的出图效率与质量 <a class="header-anchor" href="#_1-5-实战对比-不同工具的出图效率与质量" aria-label="Permalink to “1.5 实战对比：不同工具的出图效率与质量”">​</a></h2><p>怕浪猫用同一个提示词，在5个工具上做了对比测试：</p><p><strong>测试提示词</strong></p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>A serene Japanese garden with cherry blossoms, a wooden bridge over a koi pond, soft morning light, photorealistic, 8K detail</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><strong>对比结果</strong></p><table tabindex="0"><thead><tr><th>工具</th><th>生成时间</th><th>显存占用</th><th>画质评分</th><th>上手难度</th></tr></thead><tbody><tr><td>ComfyUI + FLUX.1 dev</td><td>12秒</td><td>12GB</td><td>9.5/10</td><td>中</td></tr><tr><td>ComfyUI + SDXL</td><td>8秒</td><td>8GB</td><td>8.5/10</td><td>中</td></tr><tr><td>WebUI + SDXL</td><td>10秒</td><td>9GB</td><td>8.5/10</td><td>低</td></tr><tr><td>WebUI + SD1.5</td><td>5秒</td><td>4GB</td><td>7/10</td><td>低</td></tr><tr><td>GIMP + SD插件</td><td>15秒</td><td>8GB</td><td>8/10</td><td>中</td></tr></tbody></table><p><strong>效率提升清单</strong></p><p>10个让AI图片生成效率翻倍的方法：</p><ol><li>用FLUX.1 schnell做快速草图（1-4步出图）</li><li>用SDXL+LoRA做风格统一系列</li><li>ComfyUI工作流保存为模板，一键复用</li><li>批量生成用ComfyUI API+脚本</li><li>高清修复用Tiled Upscale而非直接大图</li><li>反向提示词保持10-15个关键词，不要堆砌</li><li>种子固定后微调提示词，比随机更高效</li><li>用Civitai的预设提示词做起点</li><li>风格迁移用ControlNet而非提示词描述</li><li>最终输出用Real-ESRGAN超分到4K</li></ol><blockquote><p>工具不是越多越好，而是越精通越好。怕浪猫的建议：选一个工具深入用3个月，比5个工具浅尝辄止强10倍。</p></blockquote><hr><p>觉得有用？收藏起来，下次选工具直接照着表格抄。</p><p>你常用哪个AI图片工具？评论区说说体验，互相交流一下。</p><p>关注怕浪猫，下期我们盘点开源AI视频创作工具——从生成模型到自动剪辑，一个都不少。</p><p>系列进度 1/8 — 下一篇：AI视频创作工具的开源利器</p>',57)])])}const I=d(o,[["render",i]]);export{c as __pageData,I as default};
